async function embed(title: string, content: string) {
  const response = await ai.models.embedContent({
    model: EMBEDDING_MODEL_ID,
    contents: content,
    config: {
      taskType: "retrieval_document",
      title,
    },
  });
  return response.embeddings?.[0].values;
}

